#include <datamunge/optim/newton.hpp>
#include <cmath>
#include <stdexcept>
namespace datamunge::optim { Newton::Newton(NewtonOptions o):options_(o){} double Newton::optimize(HessianFunction& f,std::vector<double>& x)const{for(std::size_t k=0;k<options_.max_iterations;++k){auto g=f.gradient(x);double n=0;for(double v:g)n+=v*v;if(std::sqrt(n)<=options_.tolerance)break;auto h=f.hessian(x);for(std::size_t i=0;i<x.size();++i){if(i>=h.size()||h[i].size()!=x.size())throw std::invalid_argument("Newton: Hessian has wrong dimension");h[i][i]+=options_.damping;}for(std::size_t c=0;c<x.size();++c){std::size_t p=c;for(std::size_t r=c+1;r<x.size();++r)if(std::abs(h[r][c])>std::abs(h[p][c]))p=r;if(std::abs(h[p][c])<1e-15)throw std::invalid_argument("Newton: singular Hessian");std::swap(h[p],h[c]);std::swap(g[p],g[c]);for(std::size_t r=c+1;r<x.size();++r){double q=h[r][c]/h[c][c];for(std::size_t j=c;j<x.size();++j)h[r][j]-=q*h[c][j];g[r]-=q*g[c];}}for(std::size_t i=x.size();i-->0;){for(std::size_t j=i+1;j<x.size();++j)g[i]-=h[i][j]*g[j];g[i]/=h[i][i];x[i]-=g[i];}}return f.evaluate(x);}}
